 class="admin-secondary-button" data-admin-form-link href="/admin/suppliers/edit?id=<?= e($s['id']) ?>">Detalle</a><?php endif?><?php if($capabilities['suppliers.manage']??false):?><form method="post" action="/admin/suppliers/status"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($s['id']) ?>"><input type="hidden" name="active" value="<?= (int)$s['is_active']===1?'0':'1' ?>"><button class="admin-quiet-button" data-confirm="¿Confirmas el cambio de estado?"><?= (int)$s['is_active']===1?'Desactivar':'Activar' ?></button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>

